// Zero rows is the normal case. A Postgres node with alwaysOutputData emits one empty item
// for that, which would reach the sender as a malformed notice — drop it here, and do NOT set
// alwaysOutputData on this node or an empty return becomes an empty item again.
return $input.all().filter(i => (i.json || {}).appointment_id !== undefined);

const offers = $input.all().map(i => i.json || {});
const reaped = (($('Reap expired offers').first().json || {}).result || {}).reaped;
const by = offers.reduce((a, s) => { const k = s.reason || 'unknown'; a[k] = (a[k] || 0) + 1; return a; }, {});
return [{ json: { ran_at: new Date().toISOString(), expired_offers_returned_to_queue: reaped,
                  offers_made: offers.length, by_outcome: by } }];
